import numpy as np
import pandas as pd

def _quotes(path):
    df = pd.read_csv(path).dropna(subset=['rate'])
    return df.sort_values('minute')

def regrid(path, step):
    q = _quotes(path)
    grid = np.arange(q['minute'].iloc[0], q['minute'].iloc[-1] + 1, step)
    return pd.DataFrame({'minute': grid, 'rate': np.interp(grid, q['minute'], q['rate'])})

def longest_gap(path):
    return int(_quotes(path)['minute'].diff().max())

import numpy as np
import pandas as pd

def trend_table(path='lakes-level.csv'):
    df = pd.read_csv(path)
    def one(g):
        n = len(g)
        if n < 5:
            return pd.Series({'slope': np.nan, 'se': np.nan, 't': np.nan, 'n': n})
        x = g['year'].to_numpy(float)
        y = g['level_m'].to_numpy(float)
        sxx = ((x - x.mean()) ** 2).sum()
        b = ((x - x.mean()) * (y - y.mean())).sum() / sxx
        a = y.mean() - b * x.mean()
        s2 = ((y - a - b * x) ** 2).sum() / (n - 2)
        se = np.sqrt(s2 / sxx)
        return pd.Series({'slope': b, 'se': se, 't': b / se, 'n': n})
    return df.groupby('lake').apply(one, include_groups=False)

def trending(path='lakes-level.csv'):
    t = trend_table(path)['t'].dropna()
    t = t[t.abs() > 2]
    return list(t.abs().sort_values(ascending=False).index)

