import numpy as np

class OnlineOLS:
    def __init__(self, p):
        self.P = np.eye(p) * 1e8
        self.b = np.zeros(p)

    def add(self, x, y):
        x = np.asarray(x, float)
        Px = self.P @ x
        self.P = self.P - np.outer(Px, Px) / (1.0 + x @ Px)
        self.b = self.b + (self.P @ x) * (y - x @ self.b)

    def remove(self, x, y):
        x = np.asarray(x, float)
        Px = self.P @ x
        self.P = self.P + np.outer(Px, Px) / (1.0 - x @ Px)
        self.b = self.b - (self.P @ x) * (y - x @ self.b)

    def coef(self):
        return self.b.copy()

import bisect

def quote_at(quotes, times, max_gap):
    sums, counts = {}, {}
    for t, p in quotes:
        if p is None:
            continue
        sums[t] = sums.get(t, 0.0) + p
        counts[t] = counts.get(t, 0) + 1
    xs = sorted(sums)
    ys = [sums[x] / counts[x] for x in xs]
    out = []
    for t in times:
        if not xs:
            out.append(None)
            continue
        i = bisect.bisect_left(xs, t)
        if i < len(xs) and xs[i] == t:
            out.append(ys[i])
        elif i == 0:
            out.append(ys[0] if xs[0] - t <= max_gap else None)
        elif i == len(xs):
            out.append(ys[-1] if t - xs[-1] <= max_gap else None)
        elif xs[i] - xs[i - 1] > max_gap:
            out.append(None)
        else:
            x0, x1, y0, y1 = xs[i - 1], xs[i], ys[i - 1], ys[i]
            out.append(y0 + (y1 - y0) * (t - x0) / (x1 - x0))
    return out
